(7232235, 1118314, 60173, '<td valign="top">lol Nooooo!</td>', 'lol Nooooo!', '2014-06-23 12:57:34.000000', NULL, 1),
(7232267, 1119021, 163081, '<td valign="top">Why they don''t look fresh?? Nice composition</td>', 'Why they don''t look fresh?? Nice composition', '2014-06-23 13:51:10.000000', NULL, 1),
(7232315, 1119029, 98005, '<td valign="top">Very iconic!  Nice capture of the colors and contrast.  I heard on the news Saturday the first 100 people in line got a free steak sandwich?  Was that you in line ;-)</td>', 'Very iconic!  Nice capture of the colors and contrast.  I heard on the news Saturday the first 100 people in line got a free steak sandwich?  Was that you in line ;-)', '2014-06-23 16:01:50.000000', NULL, 1),
(7232344, 1119017, 128323, '<td valign="top">Wow what a capture! The composition couldn''t be more perfect.  Well done.</td>', 'Wow what a capture! The composition couldn''t be more perfect.  Well done.', '2014-06-23 17:11:06.000000', NULL, 1),
(7232346, 1119014, 128323, '<td valign="top">This looks good Jake, hope it''s doing well :)</td>', 'This looks good Jake, hope it''s doing well :)', '2014-06-23 17:12:38.000000', NULL, 1),
(7232347, 1119218, 128323, '<td valign="top">Looks sticky!  Nice shot Becky, hope it''s doing well!</td>', 'Looks sticky!  Nice shot Becky, hope it''s doing well!', '2014-06-23 17:13:46.000000', NULL, 1),
(7232348, 1118273, 128323, '<td valign="top">Wow, I guess there really is Rocky Mountain water actually going into that beer!</td>', 'Wow, I guess there really is Rocky Mountain water actually going into that beer!', '2014-06-23 17:15:10.000000', NULL, 1),
(7232349, 1118314, 128323, '<td valign="top">looks delicious :)</td>', 'looks delicious :)', '2014-06-23 17:15:27.000000', NULL, 1),
(7232350, 1119111, 128323, '<td valign="top">Very nice processing here--The colors are vibrant and match the mood of your shot, in a Normal Rockwell-esque kind of way.</td>', 'Very nice processing here--The colors are vibrant and match the mood of your shot, in a Normal Rockwell-esque kind of way.', '2014-06-23 17:17:13.000000', NULL, 1),
(7232351, 1119203, 128323, '<td valign="top">Looks good Michelle :)  Next time I have a chili dog, that''s how much cheese I''m putting on it!</td>', 'Looks good Michelle :)  Next time I have a chili dog, that''s how much cheese I''m putting on it!', '2014-06-23 17:18:09.000000', NULL, 1),
(7232353, 1119116, 128323, '<td valign="top">Hope it''s doing well Kees!  I don''t know about the Langoustines, but that Talisker sure looks good :)</td>', 'Hope it''s doing well Kees!  I don''t know about the Langoustines, but that Talisker sure looks good :)', '2014-06-23 17:18:59.000000', NULL, 1),
