(7232372, 1118273, 114225, '<td valign="top">Um, flavor. Nope. Well, ok, I guess "cat urine" is a flavor.</td>', 'Um, flavor. Nope. Well, ok, I guess "cat urine" is a flavor.', '2014-06-23 18:05:48.000000', NULL, 1),
