(7232388, 1119217, 118154, '<td valign="top">Good stuff, lovin'' the light here.</td>', 'Good stuff, lovin'' the light here.', '2014-06-23 18:32:34.000000', NULL, 1),
(7232393, 1118971, 118154, '<td valign="top">Point of focus is a little strange here, but hey ho.</td>', 'Point of focus is a little strange here, but hey ho.', '2014-06-23 18:33:56.000000', NULL, 1),
(7232395, 1119034, 118154, '<td valign="top">You bet.</td>', 'You bet.', '2014-06-23 18:34:17.000000', NULL, 1),
(7232396, 1119044, 118154, '<td valign="top">Yep.</td>', 'Yep.', '2014-06-23 18:34:51.000000', NULL, 1),
(7232411, 1118958, 176166, '<td valign="top">Very pleasing photo, but I think it only needs the first dish.</td>', 'Very pleasing photo, but I think it only needs the first dish.', '2014-06-23 19:00:44.000000', NULL, 1),
(7232412, 1119027, 176166, '<td valign="top">Nicely done</td>', 'Nicely done', '2014-06-23 19:03:10.000000', NULL, 1),
(7232414, 1118969, 176166, '<td valign="top">Well done.Maybe a bit hot in places.</td>', 'Well done.Maybe a bit hot in places.', '2014-06-23 19:08:20.000000', NULL, 1),
(7232417, 1119027, 175946, '<td valign="top">Excellent composition and exposure, perfect set up right down to the single bubble. If it were not for the sensor dust spot, I would have scored this a ten.</td>', 'Excellent composition and exposure, perfect set up right down to the single bubble. If it were not for the sensor dust spot, I would have scored this a ten.', '2014-06-23 19:25:26.000000', NULL, 1),
(7232422, 1119197, 33392, '<td valign="top">I can''t wait ''til the voting is done, because I have no idea what this is.  I hope you put an explanation in your notes.</td>', 'I can''t wait ''til the voting is done, because I have no idea what this is.  I hope you put an explanation in your notes.', '2014-06-23 19:58:56.000000', NULL, 1),
(7232423, 1119186, 33392, '<td valign="top">Normally, I like shallow DOF, but this is too shallow for the subject (at least in my opinion).  I would''ve preferred to see the whole steak rather than just the front edge.</td>', 'Normally, I like shallow DOF, but this is too shallow for the subject (at least in my opinion).  I would''ve preferred to see the whole steak rather than just the front edge.', '2014-06-23 20:00:32.000000', NULL, 1),
(7232424, 1118314, 33392, '<td valign="top">DNMC - I hope....</td>', 'DNMC - I hope....', '2014-06-23 20:02:14.000000', NULL, 1),
(7232425, 1118887, 33392, '<td valign="top">Well-composed.  It could just be me, but the greens and reds seem over saturated.</td>', 'Well-composed.  It could just be me, but the greens and reds seem over saturated.', '2014-06-23 20:07:00.000000', NULL, 1),
(7232489, 1119031, 175946, '<td valign="top">great color, composition and I like the shallow dof. It was just the hot spots that lowered my otherwise very high score</td>', 'great color, composition and I like the shallow dof. It was just the hot spots that lowered my otherwise very high score', '2014-06-23 21:21:56.000000', NULL, 1),
(7232493, 1119145, 175946, '<td valign="top">I think I may have put on two pounds just looking at these, delicious! 8</td>', 'I think I may have put on two pounds just looking at these, delicious! 8', '2014-06-23 21:26:11.000000', NULL, 1),
(7232494, 1118958, 114225, '<td valign="top">My favorite for the challenge. Clean and beautiful.</td>', 'My favorite for the challenge. Clean and beautiful.', '2014-06-23 21:28:11.000000', NULL, 1),
(7232495, 1119034, 114225, '<td valign="top">I know it''s delicious, but in this light it looks disgusting.</td>', 'I know it''s delicious, but in this light it looks disgusting.', '2014-06-23 21:28:59.000000', NULL, 1),
(7232496, 1118545, 175946, '<td valign="top">Brilliant idea beautifully done.</td>', 'Brilliant idea beautifully done.', '2014-06-23 21:32:10.000000', NULL, 1),
(7232512, 1119166, 16046, '<td valign="top">By far the best in show award, congrats, just amazing</td>', 'By far the best in show award, congrats, just amazing', '2014-06-23 23:36:06.000000', NULL, 1),
(7232513, 1119017, 16046, '<td valign="top">Top 3, well composed</td>', 'Top 3, well composed', '2014-06-23 23:36:58.000000', NULL, 1),
(7232514, 1118566, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2014-06-23 23:37:43.000000', NULL, 1),
(7232515, 1119175, 16046, '<td valign="top">Front page stuff, makes my mouth water</td>', 'Front page stuff, makes my mouth water', '2014-06-23 23:38:43.000000', NULL, 1),
(7232557, 1119208, 159196, '<td valign="top">This is the most eye catching image for me - and I''d love some!!!</td>', 'This is the most eye catching image for me - and I''d love some!!!', '2014-06-24 04:14:32.000000', NULL, 1),
(7232558, 1119014, 159196, '<td valign="top">It''s a vibrant and interesting image - aptly named!</td>', 'It''s a vibrant and interesting image - aptly named!', '2014-06-24 04:17:35.000000', NULL, 1),
(7232559, 1118392, 159196, '<td valign="top">My favorite in this challenge!</td>', 'My favorite in this challenge!', '2014-06-24 04:18:34.000000', NULL, 1),
(7232561, 1119212, 159196, '<td valign="top">Says it all!</td>', 'Says it all!', '2014-06-24 04:21:21.000000', NULL, 1),
(7232574, 1118273, 67258, '<td valign="top">So that is where it is brewed, I''ve learned something new.</td>', 'So that is where it is brewed, I''ve learned something new.', '2014-06-24 04:49:32.000000', NULL, 1),
(7232575, 1119139, 67258, '<td valign="top">We only tend to get beetroot in the UK - not sure which type it translates to.  Those carrots look great, but the brocoli does look a bit past its best.  An attractively laid out scene; the photograph has possibly suffered from compression, perhaps down to the amount of detail it contains.</td>', 'We only tend to get beetroot in the UK - not sure which type it translates to.  Those carrots look great, but the brocoli does look a bit past its best.  An attractively laid out scene; the photograph has possibly suffered from compression, perhaps down to the amount of detail it contains.', '2014-06-24 04:54:01.000000', NULL, 1),
(7232585, 1118344, 67258, '<td valign="top">OMG, that is wonderful - such a very unlikely looking creature!</td>', 'OMG, that is wonderful - such a very unlikely looking creature!', '2014-06-24 05:05:36.000000', NULL, 1),
(7232590, 1118577, 67258, '<td valign="top">I had thought fish and chips was a peculiarly British tradition!</td>', 'I had thought fish and chips was a peculiarly British tradition!', '2014-06-24 05:12:32.000000', NULL, 1),
(7232591, 1118917, 67258, '<td valign="top">Always interesting to see different vegetables from around the world.  Your tomatoes are pretty much identical to those growing on my plants, but the peppers are quite different to the varieties I can buy here, the carlic is plumper, and I have NO idea what the vaguely onion like thing is!  An aesthetically pleasing still life with good photography skills.</td>', 'Always interesting to see different vegetables from around the world.  Your tomatoes are pretty much identical to those growing on my plants, but the peppers are quite different to the varieties I can buy here, the carlic is plumper, and I have NO idea what the vaguely onion like thing is!  An aesthetically pleasing still life with good photography skills.', '2014-06-24 05:25:32.000000', NULL, 1),
(7232592, 1119145, 67258, '<td valign="top">These look interesting - I hope you are going to tell us more about them in your notes.  Focus, choice of dof, and colour palette are good.  Compositionally, I wish that it was a bit more balanced - either with the one on the right not cut-off, or also having one to the left. There seems to be something a bit odd going on where the back two tarts meet the green back-ground.</td>', 'These look interesting - I hope you are going to tell us more about them in your notes.  Focus, choice of dof, and colour palette are good.  Compositionally, I wish that it was a bit more balanced - either with the one on the right not cut-off, or also having one to the left. There seems to be something a bit odd going on where the back two tarts meet the green back-ground.', '2014-06-24 05:29:19.000000', NULL, 1),
(7232593, 1119102, 67258, '<td valign="top">So is it the jam or the cream first?  Can''t beat a cream tea, although most of mine have been from Cornwall.... I rather wish that the teapot or cup were more visible, and there does seem to be a bit of a blue-green caste.  Nonetheless a photo that inspires me to want to bake some scones when I get home from work :)</td>', 'So is it the jam or the cream first?  Can''t beat a cream tea, although most of mine have been from Cornwall.... I rather wish that the teapot or cup were more visible, and there does seem to be a bit of a blue-green caste.  Nonetheless a photo that inspires me to want to bake some scones when I get home from work :)', '2014-06-24 05:37:07.000000', NULL, 1),
(7232594, 1119045, 67258, '<td valign="top">Interesting, but the photo is too over-exposed for me to make out a lot of the detail.</td>', 'Interesting, but the photo is too over-exposed for me to make out a lot of the detail.', '2014-06-24 05:37:56.000000', NULL, 1),
(7232595, 1118545, 67258, '<td valign="top">Proper maple syrup really is delicious - I have only ever had one bottle of it; it is very expensive here in the UK.  A technically good photograph that shows the gorgeous colour of the syrup.</td>', 'Proper maple syrup really is delicious - I have only ever had one bottle of it; it is very expensive here in the UK.  A technically good photograph that shows the gorgeous colour of the syrup.', '2014-06-24 05:40:12.000000', NULL, 1),
(7232598, 1119204, 67258, '<td valign="top">The composition could do with a different arrangement I feel, in particular, the bottles and glasses are fairly rigidly lined up which takes away a little from the feeling of informality.  I also wonder whether a lower perspective would make for a stronger image.</td>', 'The composition could do with a different arrangement I feel, in particular, the bottles and glasses are fairly rigidly lined up which takes away a little from the feeling of informality.  I also wonder whether a lower perspective would make for a stronger image.', '2014-06-24 06:10:50.000000', NULL, 1),
(7232599, 1118549, 67258, '<td valign="top">The individual slices are well photographed with good textural detail and crisp focus, but for me the arrangement is way off.</td>', 'The individual slices are well photographed with good textural detail and crisp focus, but for me the arrangement is way off.', '2014-06-24 06:17:01.000000', NULL, 1),
(7232600, 1119014, 67258, '<td valign="top">That is a cracking display!  I have finally learnt waht a scallion is - we call them spring onions.  Well photographed with good detail and colour.</td>', 'That is a cracking display!  I have finally learnt waht a scallion is - we call them spring onions.  Well photographed with good detail and colour.', '2014-06-24 06:24:14.000000', NULL, 1),
(7232602, 1118424, 67258, '<td valign="top">Lacking sharpness and detail but an interesting scene.</td>', 'Lacking sharpness and detail but an interesting scene.', '2014-06-24 06:29:41.000000', NULL, 1),
(7232617, 1119175, 156466, '<td valign="top">Would love to see some more pop to this corn.  A little flat.</td>', 'Would love to see some more pop to this corn.  A little flat.', '2014-06-24 09:41:34.000000', NULL, 1),
(7232618, 1118887, 156466, '<td valign="top">Great colors and composition.  A little too structured for my tastes.</td>', 'Great colors and composition.  A little too structured for my tastes.', '2014-06-24 09:42:20.000000', NULL, 1),
(7232620, 1118964, 156466, '<td valign="top">Would love a touch more DOF, or a focal point a little further back.</td>', 'Would love a touch more DOF, or a focal point a little further back.', '2014-06-24 09:43:15.000000', NULL, 1),
(7232621, 1118545, 156466, '<td valign="top">Nice photo.  I get the composition around the handles on the edges, but I feel like it is composed a little low in the frame.  Perhaps if the pour into the top was there?</td>', 'Nice photo.  I get the composition around the handles on the edges, but I feel like it is composed a little low in the frame.  Perhaps if the pour into the top was there?', '2014-06-24 09:46:07.000000', NULL, 1),
(7232622, 1119017, 156466, '<td valign="top">Really like this.  Well done.</td>', 'Really like this.  Well done.', '2014-06-24 09:49:21.000000', NULL, 1),
(7232623, 1119160, 156466, '<td valign="top">Nice shot.  Well composed, but I find the tilted lines a bit distracting.  Perhaps if they were a little more OOF?  Still one of my favorites.  8</td>', 'Nice shot.  Well composed, but I find the tilted lines a bit distracting.  Perhaps if they were a little more OOF?  Still one of my favorites.  8', '2014-06-24 09:51:18.000000', NULL, 1),
(7232624, 1119218, 156466, '<td valign="top">Really like this shot.  Wish I could vote on it. ;)</td>', 'Really like this shot.  Wish I could vote on it. ;)', '2014-06-24 09:52:20.000000', NULL, 1),
(7232626, 1118783, 156466, '<td valign="top">I like the bottom half, but the ventilation kills it for me.  Cropped just above the open lid, this is a 7 or better, as is, 5.</td>', 'I like the bottom half, but the ventilation kills it for me.  Cropped just above the open lid, this is a 7 or better, as is, 5.', '2014-06-24 09:54:43.000000', NULL, 1),
(7232627, 1119031, 156466, '<td valign="top">Seems a touch back focused.  Nice composition otherwise.</td>', 'Seems a touch back focused.  Nice composition otherwise.', '2014-06-24 09:55:49.000000', NULL, 1),
(7232628, 1118314, 156466, '<td valign="top">Really don''t get it given the category - even if you''re cooking Chinese.</td>', 'Really don''t get it given the category - even if you''re cooking Chinese.', '2014-06-24 09:56:49.000000', NULL, 1),
(7232630, 1119199, 156466, '<td valign="top">Would love to have a closer crop.  Great colors otherwise.</td>', 'Would love to have a closer crop.  Great colors otherwise.', '2014-06-24 09:57:26.000000', NULL, 1),
(7232631, 1118809, 156466, '<td valign="top">Nice composition and colors.  Would love the dish to be sharper.</td>', 'Nice composition and colors.  Would love the dish to be sharper.', '2014-06-24 09:58:05.000000', NULL, 1),
(7232632, 1119204, 156466, '<td valign="top">Makes me miss the Pacific Northwest.</td>', 'Makes me miss the Pacific Northwest.', '2014-06-24 09:58:36.000000', NULL, 1),
(7232633, 1118917, 156466, '<td valign="top">Nicely composed, if a little dark.  7</td>', 'Nicely composed, if a little dark.  7', '2014-06-24 09:59:07.000000', NULL, 1),
(7232634, 1118969, 156466, '<td valign="top">A little tilted to the right, and high on the structure, particularly in the background.</td>', 'A little tilted to the right, and high on the structure, particularly in the background.', '2014-06-24 10:03:35.000000', NULL, 1),
(7232635, 1119186, 156466, '<td valign="top">A little too narrow on the DOF?</td>', 'A little too narrow on the DOF?', '2014-06-24 10:04:52.000000', NULL, 1),
(7232637, 1119029, 156466, '<td valign="top">I won''t penalize you for your choice since it''s the more photogenic. And if I knew you were across the street eating while you took it, I might give you bonus points. ;)</td>', 'I won''t penalize you for your choice since it''s the more photogenic. And if I knew you were across the street eating while you took it, I might give you bonus points. ;)', '2014-06-24 10:06:56.000000', NULL, 1),
(7232638, 1119116, 156466, '<td valign="top">Lovely shot.  Wish I could vote on it.</td>', 'Lovely shot.  Wish I could vote on it.', '2014-06-24 10:07:15.000000', NULL, 1),
(7232641, 1119212, 156466, '<td valign="top">I''m trying to figure out if I find the shadow in the beer distracting or appealing.  I''m thinking if you hadn''t had a sip or two first it might have presented better - but I can''t blame you if you did.  :)  7</td>', 'I''m trying to figure out if I find the shadow in the beer distracting or appealing.  I''m thinking if you hadn''t had a sip or two first it might have presented better - but I can''t blame you if you did.  :)  7', '2014-06-24 10:09:46.000000', NULL, 1),
(7232642, 1118549, 156466, '<td valign="top">Nice color, unappealing composition.</td>', 'Nice color, unappealing composition.', '2014-06-24 10:11:21.000000', NULL, 1),
(7232663, 1119208, 67258, '<td valign="top">An interesting image that looks as though it is well taken, BUT, I haven''t a clue what I am looking at.  All I can tell is it is something cooked with baby tomatos on it.  It would be helpful to have some other clues - either in the title or in the composition, to give context.</td>', 'An interesting image that looks as though it is well taken, BUT, I haven''t a clue what I am looking at.  All I can tell is it is something cooked with baby tomatos on it.  It would be helpful to have some other clues - either in the title or in the composition, to give context.', '2014-06-24 12:51:56.000000', NULL, 1),
(7232664, 1118314, 67258, '<td valign="top">Noooo!  I love kittens.  I don''t want to eat kittens :(((((</td>', 'Noooo!  I love kittens.  I don''t want to eat kittens :(((((', '2014-06-24 12:52:54.000000', NULL, 1),
